using namespace std;using ll=long long;const ll MOD=1000000007;
static void task1(){int n;cin>>n;vector<int>a(n),b(n);for(int&x:a)cin>>x;for(int&x:b)cin>>x;vector<int>ans;if(SLOW){for(int x:a){int best=0;for(int j=1;j<(int)b.size();j++)if(MUT?(x+b[j])%n>(x+b[best])%n:(x+b[j])%n<(x+b[best])%n)best=j;ans.push_back((x+b[best])%n);b.erase(b.begin()+best);}}else{multiset<int>s(b.begin(),b.end());for(int x:a){auto it=s.lower_bound(n-x);if(MUT){if(it==s.begin())it=prev(s.end());else --it;}else if(it==s.end())it=s.begin();ans.push_back((x+*it)%n);s.erase(it);}}for(int i=0;i<n;i++)cout<<(i?" ":"")<<ans[i];cout<<'\n';}
static void task2(){int t;cin>>t;while(t--){int n;ll k;cin>>n>>k;vector<ll>a(n);for(auto&x:a)cin>>x;if(SLOW){while(k--){ll d=MUT?*min_element(a.begin(),a.end()):*max_element(a.begin(),a.end());for(auto&x:a)x=d-x;}}else{ll lo=*min_element(a.begin(),a.end()),hi=*max_element(a.begin(),a.end());for(auto&x:a)x=k%2?(MUT?lo-x:hi-x):(MUT?x-hi:x-lo);}for(int i=0;i<n;i++)cout<<(i?" ":"")<<a[i];cout<<'\n';}}
static void task3(){int n,k,q;cin>>n>>k>>q;vector<ll>v(n);for(auto&x:v)cin>>x;vector<bool>active(n);set<pair<ll,int>>shown;while(q--){int type,id;cin>>type>>id;--id;if(type==1){active[id]=true;if(!SLOW){shown.insert({v[id],id});if((int)shown.size()>k){if(MUT)shown.erase(prev(shown.end()));else shown.erase(shown.begin());}}}else{bool yes=false;if(SLOW){int better=0;for(int i=0;i<n;i++)if(active[i]&&(MUT?v[i]<v[id]:v[i]>v[id]))better++;yes=active[id]&&better<k;}else yes=shown.count({v[id],id});cout<<(yes?"YES":"NO")<<'\n';}}}
static void task4(){int n,q;cin>>n>>q;vector<ll>until(n+1);set<int>free;for(int i=1;i<=n;i++)free.insert(i);priority_queue<pair<ll,int>,vector<pair<ll,int>>,greater<pair<ll,int>>>busy;while(q--){ll t,d;int k;cin>>t>>k>>d;vector<int>chosen;if(SLOW){vector<int>candidates;for(int i=1;i<=n;i++)if(until[i]<=t)candidates.push_back(i);if((int)candidates.size()>=k){if(MUT)reverse(candidates.begin(),candidates.end());chosen.assign(candidates.begin(),candidates.begin()+k);for(int i:chosen)until[i]=t+d;}}else{while(!busy.empty()&&busy.top().first<=t){free.insert(busy.top().second);busy.pop();}if((int)free.size()>=k)while(k--){auto it=MUT?prev(free.end()):free.begin();int id=*it;chosen.push_back(id);free.erase(it);busy.push({t+d,id});}}if(chosen.empty())cout<<-1<<'\n';else cout<<accumulate(chosen.begin(),chosen.end(),0LL)<<'\n';}}
static void task5(){int h,w;cin>>h>>w;vector<string>a(h);for(auto&s:a)cin>>s;vector<array<int,26>>row(h),col(w);if(!SLOW)for(int i=0;i<h;i++)for(int j=0;j<w;j++)row[i][a[i][j]-'a']++,col[j][a[i][j]-'a']++;for(int i=0;i<h;i++)for(int j=0;j<w;j++){int x=0,y=0;if(SLOW){for(int k=0;k<w;k++)x+=a[i][k]==a[i][j];for(int k=0;k<h;k++)y+=a[k][j]==a[i][j];}else x=row[i][a[i][j]-'a'],y=col[j][a[i][j]-'a'];if(MUT?(x>1&&y>1):(x==1&&y==1))cout<<a[i][j];}cout<<'\n';}
static void task6(){int n;cin>>n;vector<ll>a(n);for(auto&v:a)cin>>v;ll ans=0;if(SLOW){for(int i=0;i<n;i++){ll target=a[i];for(int j=MUT?i:0;j<(MUT?n:i+1);j++)target=max(target,a[j]);ans+=target-a[i];}}else{ll bound=0;for(int t=0;t<n;t++){int i=MUT?n-1-t:t;bound=max(bound,a[i]);ans+=bound-a[i];}}cout<<ans<<'\n';}
static void task7(){int n;cin>>n;vector<ll>a(n);for(auto&v:a)cin>>v;ll ans=0;if(SLOW){for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)ans=(ans+((MUT?a[i]&a[j]:a[i]^a[j])%MOD))%MOD;}else{ll power=1;for(int b=0;b<60;b++){ll count=0;for(ll x:a)count+=(x>>b)&1;ll pairs=MUT?count*(count-1)/2:count*(n-count);ans=(ans+(pairs%MOD)*power)%MOD;power=power*2%MOD;}}cout<<ans<<'\n';}
static void task8(){int h,w;cin>>h>>w;vector<string>a(h);for(auto&s:a)cin>>s;vector<pair<int,int>>bombs;if(SLOW)for(int i=0;i<h;i++)for(int j=0;j<w;j++)if(a[i][j]=='#')bombs.push_back({i,j});for(int i=0;i<h;i++){for(int j=0;j<w;j++){if(a[i][j]=='#'){cout<<'#';continue;}int ans=0;if(SLOW){for(auto[x,y]:bombs)ans+=MUT?abs(x-i)+abs(y-j)==1:max(abs(x-i),abs(y-j))==1;}else for(int di=-1;di<=1;di++)for(int dj=-1;dj<=1;dj++){if(MUT?abs(di)+abs(dj)!=1:di==0&&dj==0)continue;int x=i+di,y=j+dj;if(x>=0&&x<h&&y>=0&&y<w)ans+=a[x][y]=='#';}cout<<ans;}cout<<'\n';}}
static void task9(){string a,b;while(cin>>a>>b){int n=a.size(),m=b.size(),ans=0;if(SLOW){for(int i=0;i<n;i++)for(int j=0;j<m;j++){int k=0;while(i+k<n&&j+k<m&&a[i+k]==b[j+k])k++;ans=max(ans,k);}}else{vector<int>old(m+1),cur(m+1);for(int i=1;i<=n;i++){cur[0]=0;for(int j=1;j<=m;j++){if(MUT)cur[j]=a[i-1]==b[j-1]?old[j-1]+1:max(old[j],cur[j-1]);else cur[j]=a[i-1]==b[j-1]?old[j-1]+1:0;ans=max(ans,cur[j]);}old.swap(cur);}}cout<<ans<<'\n';}}
static void task10(){int n,m;cin>>n;vector<int>a(n);for(int&v:a)cin>>v;cin>>m;vector<int>b(m);for(int&v:b)cin>>v;int best=MUT?INT_MAX:-1,count=0;auto accept=[&](int ratio){if(MUT?ratio<best:ratio>best)best=ratio,count=1;else if(ratio==best)count++;};if(SLOW){for(int x:a)for(int y:b)if(y%x==0)accept(y/x);}else{int hi=b.back();vector<bool>present(hi+1);for(int y:b)present[y]=true;for(int x:a)for(int y=x;y<=hi;y+=x)if(present[y])accept(y/x);}cout<<count<<'\n';}
static void task11(){int n;cin>>n;vector<string>a(n);for(auto&s:a)cin>>s;int ans=0;if(SLOW){vector<array<int,26>>d(n);for(int i=0;i<n;i++){int u=a[i].front()-'a',v=a[i].back()-'a',len=a[i].size();d[i][u]=len;for(int j=0;j<i;j++)if(a[j].back()==a[i].front())for(int c=0;c<26;c++)if(d[j][c])d[i][c]=max(d[i][c],d[j][c]+len);for(int c=0;c<26;c++)if(MUT?c!=v:c==v)ans=max(ans,d[i][c]);}}else{int d[26][26]={};for(auto&s:a){int u=s.front()-'a',v=s.back()-'a',len=s.size();for(int c=0;c<26;c++)if(d[c][u])d[c][v]=max(d[c][v],d[c][u]+len);d[u][v]=max(d[u][v],len);}for(int u=0;u<26;u++)for(int v=0;v<26;v++)if(MUT?u!=v:u==v)ans=max(ans,d[u][v]);}cout<<ans<<'\n';}
static void task12(){int t;cin>>t;while(t--){int p;cin>>p;int ans;if(SLOW){vector<int>d(p+1,INT_MAX/2);d[0]=0;for(int x=1;x<=p;x++)for(int c=1;c<=2048&&c<=x;c*=2)d[x]=min(d[x],d[x-c]+1);ans=d[p];}else if(MUT)ans=p>4095?-1:__builtin_popcount((unsigned)p);else ans=p/2048+__builtin_popcount((unsigned)(p%2048));cout<<ans<<'\n';}}
static void task13(){int n;cin>>n;vector<int>a(n);for(int&v:a)cin>>v;bool yes=false;int target=MUT?180:0;if(SLOW){for(unsigned long long mask=0;mask<(1ULL<<n);mask++){int sum=0;for(int i=0;i<n;i++)sum+=(mask>>i&1)?a[i]:-a[i];if((sum%360+360)%360==target){yes=true;break;}}}else{array<bool,360>d{};d[0]=true;for(int v:a){array<bool,360>nd{};for(int j=0;j<360;j++)if(d[j])nd[(j+v)%360]=nd[(j-v+360)%360]=true;d=nd;}yes=d[target];}cout<<(yes?"YES":"NO")<<'\n';}
static void task14(){int n;cin>>n;vector<int>a(n-1),b(n-1),answer;for(int&v:a)cin>>v;for(int&v:b)cin>>v;auto fits=[&](int i,int x,int y){return (MUT?(x^y):(x|y))==a[i]&&(x&y)==b[i];};if(SLOW){vector<int>t(n);while(true){bool ok=true;for(int i=0;i+1<n;i++)if(!fits(i,t[i],t[i+1])){ok=false;break;}if(ok){answer=t;break;}int j=n-1;while(j>=0&&t[j]==3)t[j--]=0;if(j<0)break;t[j]++;}}else{vector<array<int,4>>parent(n);for(auto&x:parent)x.fill(-1);for(int x=0;x<4;x++)parent[0][x]=x;for(int i=1;i<n;i++)for(int y=0;y<4;y++)for(int x=0;x<4;x++)if(parent[i-1][x]>=0&&fits(i-1,x,y)){parent[i][y]=x;break;}for(int x=0;x<4;x++)if(parent[n-1][x]>=0){answer.resize(n);answer[n-1]=x;for(int i=n-1;i>0;i--)answer[i-1]=parent[i][answer[i]];break;}}if(answer.empty())cout<<"NO\n";else{cout<<"YES\n";for(int i=0;i<n;i++)cout<<(i?" ":"")<<answer[i];cout<<'\n';}}
static void task15(){int q;cin>>q;while(q--){int n;cin>>n;vector<int>a(n);for(int&v:a)cin>>v;bool yes=false;if(SLOW){vector<int>v(n),up(n),down(n);iota(up.begin(),up.end(),1);down=up;reverse(down.begin(),down.end());for(int start=0;start<n;start++){for(int i=0;i<n;i++)v[i]=a[(start+i)%n];if(v==up||(!MUT&&v==down)){yes=true;break;}}}else{bool up=true,down=true;for(int i=0;i<n;i++){up&=a[(i+1)%n]==a[i]%n+1;down&=a[(i+1)%n]==(a[i]+n-2)%n+1;}yes=up||(!MUT&&down);}cout<<(yes?"YES":"NO")<<'\n';}}
static void task16(){ll a,b,c;cin>>a>>b>>c;ll ans=0;auto use=[&](ll d){if(a<=d&&d<=b)ans+=MUT?d:1;};if(SLOW){for(ll d=a;d<=b;d++)if(c%d==0)use(d);}else for(ll d=1;d*d<=c;d++)if(c%d==0){use(d);if(c/d!=d)use(c/d);}cout<<ans<<'\n';}
static void task17(){int n,m;cin>>n>>m;vector<unsigned long long>a(m);for(auto&row:a){int k;cin>>k;while(k--){int v;cin>>v;row|=1ULL<<(v-1);}}for(auto&row:a){int p;cin>>p;row|=(unsigned long long)(p^MUT)<<n;}unsigned long long ans=0,mask=(1ULL<<n)-1;if(SLOW){for(unsigned long long state=0;state<=mask;state++){bool ok=true;for(auto row:a)if((__builtin_parityll((row&mask)&state))!=(int)(row>>n)){ok=false;break;}ans+=ok;}}else{int rank=0;for(int col=0;col<n;col++){int pivot=rank;while(pivot<m&&!(a[pivot]>>col&1))pivot++;if(pivot==m)continue;swap(a[pivot],a[rank]);for(int j=0;j<m;j++)if(j!=rank&&(a[j]>>col&1))a[j]^=a[rank];rank++;}bool ok=true;for(auto row:a)if((row&mask)==0&&(row>>n))ok=false;if(ok)ans=1ULL<<(n-rank);}cout<<ans<<'\n';}
static void task18(){int t;cin>>t;while(t--){int l,r;cin>>l>>r;vector<bool>prime(r-l+1,true);if(SLOW){for(int v=l;v<=r;v++){bool p=v>=2;for(int d=2;1LL*d*d<=v;d++)if(v%d==0){p=false;break;}prime[v-l]=p;}}else{int limit=sqrt(r);vector<bool>small(limit+1,true);for(int p=2;p<=limit;p++)if(small[p]){for(int j=p*p;j<=limit;j+=p)small[j]=false;for(ll j=max(1LL*p*p,1LL*(l+p-1)/p*p);j<=r;j+=p)prime[j-l]=false;}if(l==1)prime[0]=false;}for(int v=l;v<=r;v++)if(v>=2&&(MUT?!prime[v-l]:prime[v-l]))cout<<v<<'\n';cout<<'\n';}}
static void task19(){int t;cin>>t;while(t--){int n,k;cin>>n>>k;vector<string>dict(n);for(auto&s:dict)cin>>s;vector<vector<string>>phrases(k);unordered_map<string,int>counts;for(auto&v:phrases){int l;cin>>l;v.resize(l);for(auto&s:v)cin>>s;if(!SLOW){set<string>seen(v.begin(),v.end());for(auto&s:seen)counts[s]++;}}for(int i=0;i<n;i++){int count=0;if(SLOW){for(auto&v:phrases){bool found=false;for(auto&s:v)if(s==dict[i]){found=true;break;}count+=found;}}else count=counts[dict[i]];cout<<(i?" ":"")<<((MUT?count==k:count>0)?"YES":"NO");}cout<<'\n';}}
